package com.sarathi.api.activity;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.sarathi.api.common.ApiException;
import com.sarathi.api.security.UserPrincipal;
import jakarta.validation.Valid;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController
public class ActivityController {
 private final JdbcTemplate db;private final ObjectMapper json;
 public ActivityController(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}
 @GetMapping("/api/operators") public Map<String,Object> operators(@RequestParam(required=false) String district,@RequestParam(required=false) String skill,@RequestParam(defaultValue="20") int limit){StringBuilder sql=new StringBuilder("SELECT u.id,u.full_name,u.village,u.district,p.skills,p.daily_rate_paise,p.service_area_km,p.experience_years,p.verified_at,p.rating,p.rating_count FROM operator_profiles p JOIN users u ON u.id=p.user_id WHERE u.active=1 AND p.available=1");List<Object> args=new ArrayList<>();if(district!=null&&!district.isBlank()){sql.append(" AND lower(u.district)=lower(?)");args.add(district.trim());}if(skill!=null&&!skill.isBlank()){sql.append(" AND JSON_CONTAINS(p.skills,JSON_QUOTE(?))=1");args.add(skill.toUpperCase(Locale.ROOT));}sql.append(" ORDER BY p.verified_at DESC,p.rating DESC LIMIT ?");args.add(Math.min(50,Math.max(1,limit)));return Map.of("items",db.queryForList(sql.toString(),args.toArray()));}
 @PutMapping("/api/operators/me") @PreAuthorize("hasAuthority('OPERATOR')") public Map<String,Object> updateOperator(@AuthenticationPrincipal UserPrincipal user,@Valid @RequestBody ActivityDtos.OperatorUpdate r){String skills=json(r.skills());db.update("INSERT INTO operator_profiles(user_id,skills,daily_rate_paise,experience_years,service_area_km,available) VALUES(?,CAST(? AS JSON),?,?,?,?) ON DUPLICATE KEY UPDATE skills=VALUES(skills),daily_rate_paise=VALUES(daily_rate_paise),experience_years=VALUES(experience_years),service_area_km=VALUES(service_area_km),available=VALUES(available)",user.id(),skills,r.dailyRatePaise(),r.experienceYears(),r.serviceAreaKm(),r.available());return Map.of("profile",db.queryForMap("SELECT * FROM operator_profiles WHERE user_id=?",user.id()));}
 @GetMapping("/api/maintenance") @PreAuthorize("hasAnyAuthority('OWNER','ADMIN')") public Map<String,Object> maintenance(@AuthenticationPrincipal UserPrincipal user){return Map.of("items",db.queryForList("SELECT m.*,e.name AS equipment_name FROM maintenance_logs m JOIN equipment e ON e.id=m.equipment_id WHERE e.owner_id=? ORDER BY m.service_date DESC,m.created_at DESC",user.id()));}
 @PostMapping("/api/maintenance") @PreAuthorize("hasAnyAuthority('OWNER','ADMIN')") @Transactional public Map<String,Object> logMaintenance(@AuthenticationPrincipal UserPrincipal user,@Valid @RequestBody ActivityDtos.MaintenanceRequest r){var equipment=db.queryForList("SELECT id FROM equipment WHERE id=? AND owner_id=? FOR UPDATE",r.equipmentId(),user.id());if(equipment.isEmpty())throw ApiException.notFound("Equipment not found.");if(r.makesUnavailable()){if(!db.queryForList("SELECT id FROM bookings WHERE equipment_id=? AND status IN ('PENDING','CONFIRMED','IN_PROGRESS') AND end_date>CURRENT_DATE LIMIT 1",r.equipmentId()).isEmpty())throw ApiException.conflict("Resolve upcoming bookings before marking this machine unavailable.");db.update("UPDATE equipment SET status='MAINTENANCE' WHERE id=?",r.equipmentId());}String id=UUID.randomUUID().toString();db.update("INSERT INTO maintenance_logs(id,equipment_id,created_by,service_date,operating_hours,summary,cost_paise,makes_unavailable,next_service_date) VALUES(?,?,?,?,?,?,?,?,?)",id,r.equipmentId(),user.id(),r.serviceDate(),r.operatingHours(),r.summary(),r.costPaise(),r.makesUnavailable(),r.nextServiceDate());audit(user.id(),"MAINTENANCE_LOGGED","EQUIPMENT",r.equipmentId());return Map.of("log",db.queryForMap("SELECT * FROM maintenance_logs WHERE id=?",id));}
 @GetMapping("/api/payments") @PreAuthorize("isAuthenticated()") public Map<String,Object> payments(@AuthenticationPrincipal UserPrincipal user){return Map.of("items",db.queryForList("SELECT p.*,p.rental_amount_paise AS amount_paise,e.name AS equipment_name,r.full_name AS payer_name,o.full_name AS payee_name FROM payments p JOIN bookings b ON b.id=p.booking_id JOIN equipment e ON e.id=b.equipment_id JOIN users r ON r.id=p.payer_id JOIN users o ON o.id=p.payee_id WHERE p.payer_id=? OR p.payee_id=? ORDER BY p.created_at DESC",user.id(),user.id()));}
 @PatchMapping("/api/payments/{id}/mark-paid") @PreAuthorize("hasAnyAuthority('OWNER','ADMIN')") @Transactional public Map<String,Object> markPaid(@AuthenticationPrincipal UserPrincipal user,@PathVariable String id,@RequestBody(required=false) ActivityDtos.MarkPaidRequest r){var rows=db.queryForList("SELECT p.status,b.status AS booking_status,e.owner_id FROM payments p JOIN bookings b ON b.id=p.booking_id JOIN equipment e ON e.id=b.equipment_id WHERE p.id=? FOR UPDATE",id);if(rows.isEmpty()||!user.id().equals(rows.get(0).get("owner_id"))&&!user.role().equals("ADMIN"))throw ApiException.notFound("Payment record not found.");if(!"PENDING".equals(rows.get(0).get("status")))throw ApiException.conflict("Only pending payment records can be updated.");if("CANCELLED".equals(rows.get(0).get("booking_status")))throw ApiException.conflict("Cancelled bookings cannot be marked paid.");db.update("UPDATE payments SET status='PAID',paid_at=CURRENT_TIMESTAMP(6),recorded_by=?,method=?,reference=? WHERE id=?",user.id(),r==null||r.method()==null?"OFFLINE":r.method(),r==null?null:r.reference(),id);audit(user.id(),"PAYMENT_MARKED_PAID","PAYMENT",id);return Map.of("payment",db.queryForMap("SELECT * FROM payments WHERE id=?",id),"note","Offline demo payment record only; Sarathi does not process money.");}
 @PostMapping("/api/feedback") @PreAuthorize("isAuthenticated()") public Map<String,Object> feedback(@AuthenticationPrincipal UserPrincipal user,@Valid @RequestBody ActivityDtos.FeedbackRequest r){String id=UUID.randomUUID().toString();db.update("INSERT INTO feedback(id,user_id,rating,category,message) VALUES(?,?,?,?,?)",id,user.id(),r.rating(),r.category()==null?"GENERAL":r.category(),r.message());return Map.of("feedback",db.queryForMap("SELECT * FROM feedback WHERE id=?",id));}
 @GetMapping("/api/community") public Map<String,Object> community(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int limit){int p=Math.max(1,page),l=Math.min(50,Math.max(1,limit));return Map.of("items",db.queryForList("SELECT p.id,p.body,p.created_at,u.id AS author_id,u.full_name,u.village,u.district FROM community_posts p JOIN users u ON u.id=p.author_id WHERE p.deleted_at IS NULL ORDER BY p.created_at DESC LIMIT ? OFFSET ?",l,(p-1)*l),"page",p,"limit",l);}
 @PostMapping("/api/community") @PreAuthorize("isAuthenticated()") public Map<String,Object> post(@AuthenticationPrincipal UserPrincipal user,@Valid @RequestBody ActivityDtos.PostRequest r){String id=UUID.randomUUID().toString();db.update("INSERT INTO community_posts(id,author_id,body) VALUES(?,?,?)",id,user.id(),r.body().trim());return Map.of("post",db.queryForMap("SELECT * FROM community_posts WHERE id=?",id));}
 @DeleteMapping("/api/community/{id}") @PreAuthorize("isAuthenticated()") public void deletePost(@AuthenticationPrincipal UserPrincipal user,@PathVariable String id){int n=db.update("UPDATE community_posts SET deleted_at=CURRENT_TIMESTAMP(6) WHERE id=? AND author_id=? AND deleted_at IS NULL",id,user.id());if(n==0)throw ApiException.notFound("Post not found.");}
 @GetMapping("/api/analytics/owner") @PreAuthorize("hasAnyAuthority('OWNER','ADMIN')") public Map<String,Object> ownerAnalytics(@AuthenticationPrincipal UserPrincipal user){return Map.of("fleet",db.queryForMap("SELECT COUNT(*) equipment_count,SUM(status='AVAILABLE') available_count,COALESCE(AVG(average_rating),0) average_rating FROM equipment WHERE owner_id=?",user.id()),"bookings",db.queryForMap("SELECT SUM(status IN ('PENDING','CONFIRMED','IN_PROGRESS')) active_bookings,SUM(status='COMPLETED') completed_bookings FROM bookings b JOIN equipment e ON e.id=b.equipment_id WHERE e.owner_id=?",user.id()),"payments",db.queryForMap("SELECT COALESCE(SUM(IF(status='PAID',rental_amount_paise+transport_paise+operator_paise,0)),0) paid_paise,COALESCE(SUM(status='PENDING'),0) pending_count FROM payments WHERE payee_id=? AND created_at>=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')",user.id()));}
 @GetMapping("/api/analytics/network") @PreAuthorize("hasAuthority('ADMIN')") public Map<String,Object> networkAnalytics(){return Map.of("network",db.queryForMap("SELECT (SELECT COUNT(*) FROM equipment) equipment_total,(SELECT COUNT(*) FROM bookings WHERE status IN ('PENDING','CONFIRMED','IN_PROGRESS')) active_bookings,(SELECT COUNT(*) FROM users WHERE role='FARMER' AND active=1) farmers,(SELECT COUNT(*) FROM users WHERE role='OWNER' AND active=1) owners,(SELECT COUNT(*) FROM users WHERE role='OPERATOR' AND active=1) operators"));}
 private String json(Object value){try{return json.writeValueAsString(value);}catch(JsonProcessingException e){throw ApiException.badRequest("Invalid JSON data.");}}
 private void audit(String actor,String action,String type,String entity){db.update("INSERT INTO audit_events(actor_id,action,entity_type,entity_id,metadata) VALUES(?,?,?,?,JSON_OBJECT())",actor,action,type,entity);}
}
